using System;
using PX.Data;
using PX.Data.BQL.Fluent;
using PX.Objects.PO;

namespace StudioB.Containers
{
    public class ContainerMaint : PXGraph<ContainerMaint, UsrContainer>
    {
        public static bool IsActive() => true;

        #region Views
        public SelectFrom<UsrContainer>.View Container;

        public SelectFrom<UsrContainerEvent>
            .Where<UsrContainerEvent.containerID.IsEqual<UsrContainer.containerID.FromCurrent>>
            .OrderBy<UsrContainerEvent.eventDateTime.Desc>
            .View Events;

        public SelectFrom<UsrContainerPOLink>
            .Where<UsrContainerPOLink.containerID.IsEqual<UsrContainer.containerID.FromCurrent>>
            .View POLinks;
        #endregion

        #region Actions
        public PXAction<UsrContainer> RefreshTracking;
        [PXButton(CommitChanges = true)]
        [PXUIField(DisplayName = "Refresh Tracking", MapEnableRights = PXCacheRights.Update)]
        protected void refreshTracking()
        {
            // Placeholder — tracking refresh triggered via API from webhook-router.
            // This action can be wired to call the carrier API directly in a future phase,
            // or to push a message to the webhook-router BullMQ queue.
            UsrContainer container = Container.Current;
            if (container == null) return;

            container.LastSyncDate = DateTime.UtcNow;
            Container.Update(container);
            Actions.PressSave();
        }
        #endregion

        #region Event Handlers
        protected void _(Events.RowSelected<UsrContainer> e)
        {
            if (e.Row == null) return;
            bool isActive = e.Row.Status != "DELIVERED" && e.Row.Status != "CANCELLED";
            PXUIFieldAttribute.SetEnabled<UsrContainer.containerCD>(e.Cache, e.Row, string.IsNullOrEmpty(e.Row.ContainerCD));
            RefreshTracking.SetEnabled(isActive);
        }
        #endregion

        #region Persist Override
        public override void Persist()
        {
            UsrContainer container = Container.Current;
            base.Persist();

            // After save, propagate ETA to linked PO headers and lines
            if (container?.ETA != null)
            {
                var poRefs = new System.Collections.Generic.List<Tuple<string, string, int?>>();
                foreach (UsrContainerPOLink link in POLinks.Select())
                {
                    poRefs.Add(Tuple.Create(link.OrderType, link.OrderNbr, link.LineNbr));
                }
                if (poRefs.Count > 0)
                {
                    ContainerDatePropagation.PropagateArrivalDate(container.ETA, poRefs);
                }
            }
        }
        #endregion
    }
}

using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace StudioB.Containers
{
    public class AesthetikContainersInstall : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null) { WriteLog("[AesthetikContainers] No ProjectX connection string — skipping DDL"); return; }
                string connStr = cs.ConnectionString + ";TrustServerCertificate=True";

                using (var conn = new SqlConnection(connStr))
                {
                    conn.Open();

                    // ── Container Tracking Tables ──────────────────────────────
                    EnsureTable(conn, "UsrContainer", @"
                        CompanyID int NOT NULL DEFAULT 0,
                        ContainerID int IDENTITY(1,1) NOT NULL,
                        ContainerCD nvarchar(20) NOT NULL,
                        CarrierCode nvarchar(20) NOT NULL DEFAULT 'OTHER',
                        BookingRef nvarchar(50) NULL,
                        BillOfLading nvarchar(50) NULL,
                        VesselName nvarchar(50) NULL,
                        VesselIMO nvarchar(10) NULL,
                        VoyageNbr nvarchar(30) NULL,
                        PortOfLoading nvarchar(10) NULL,
                        PortOfDischarge nvarchar(10) NULL,
                        ETD datetime NULL,
                        ATD datetime NULL,
                        ETA datetime NULL,
                        ATA datetime NULL,
                        Status nvarchar(20) NOT NULL DEFAULT 'BOOKED',
                        ContainerType nvarchar(10) NULL,
                        SealNbr nvarchar(20) NULL,
                        LastEventCode nvarchar(20) NULL,
                        LastEventDate datetime NULL,
                        LastSyncDate datetime NULL,
                        NoteID uniqueidentifier NULL,
                        CreatedByID uniqueidentifier NULL,
                        CreatedByScreenID char(8) NULL,
                        CreatedDateTime datetime NULL,
                        LastModifiedByID uniqueidentifier NULL,
                        LastModifiedByScreenID char(8) NULL,
                        LastModifiedDateTime datetime NULL,
                        tstamp timestamp NOT NULL,
                        CONSTRAINT PK_UsrContainer PRIMARY KEY (CompanyID, ContainerID)
                    ");

                    EnsureTable(conn, "UsrContainerEvent", @"
                        CompanyID int NOT NULL DEFAULT 0,
                        EventID int IDENTITY(1,1) NOT NULL,
                        ContainerID int NOT NULL,
                        CarrierEventCode nvarchar(20) NOT NULL DEFAULT '',
                        NormalizedEventCode nvarchar(20) NOT NULL DEFAULT '',
                        EventDateTime datetime NOT NULL DEFAULT GETUTCDATE(),
                        EventClassifier nvarchar(10) NULL,
                        LocationName nvarchar(100) NULL,
                        LocationCode nvarchar(10) NULL,
                        VesselName nvarchar(50) NULL,
                        Description nvarchar(255) NULL,
                        RawPayload nvarchar(MAX) NULL,
                        CreatedDateTime datetime NOT NULL DEFAULT GETUTCDATE(),
                        CONSTRAINT PK_UsrContainerEvent PRIMARY KEY (CompanyID, EventID)
                    ");

                    EnsureTable(conn, "UsrContainerPOLink", @"
                        CompanyID int NOT NULL DEFAULT 0,
                        LinkID int IDENTITY(1,1) NOT NULL,
                        ContainerID int NOT NULL,
                        OrderType nvarchar(2) NOT NULL DEFAULT 'RO',
                        OrderNbr nvarchar(15) NOT NULL DEFAULT '',
                        LineNbr int NULL,
                        CONSTRAINT PK_UsrContainerPOLink PRIMARY KEY (CompanyID, LinkID)
                    ");

                    // Indexes
                    EnsureIndex(conn, "UsrContainer", "IX_UsrContainer_ContainerCD", "CompanyID, ContainerCD");
                    EnsureIndex(conn, "UsrContainer", "IX_UsrContainer_Status", "CompanyID, Status");
                    EnsureIndex(conn, "UsrContainerEvent", "IX_UsrContainerEvent_ContainerID", "CompanyID, ContainerID, EventDateTime DESC");
                    EnsureIndex(conn, "UsrContainerPOLink", "IX_UsrContainerPOLink_ContainerID", "CompanyID, ContainerID");
                    EnsureIndex(conn, "UsrContainerPOLink", "IX_UsrContainerPOLink_PO", "CompanyID, OrderType, OrderNbr");

                    // SOShipment container fields
                    EnsureColumn(conn, "SOShipment", "UsrIncludeInContainer", "bit NULL DEFAULT 0");
                    EnsureColumn(conn, "SOShipment", "UsrContainerID", "int NULL");

                    // ── InventoryItem tariff/customs fields ────────────────────
                    EnsureColumn(conn, "InventoryItem", "UsrDutyRate", "decimal(25,4) NULL");
                    EnsureColumn(conn, "InventoryItem", "UsrFiberContent", "nvarchar(100) NULL");
                    EnsureColumn(conn, "InventoryItem", "UsrPreferentialTariff", "bit NULL");
                    EnsureColumn(conn, "InventoryItem", "UsrFreightClass", "nvarchar(15) NULL");

                    // ── POReceiptLine landed cost fields ───────────────────────
                    EnsureColumn(conn, "POReceiptLine", "UsrActualDutyAmt", "decimal(25,4) NULL");
                    EnsureColumn(conn, "POReceiptLine", "UsrActualFreightAmt", "decimal(25,4) NULL");
                    EnsureColumn(conn, "POReceiptLine", "UsrBrokerageAmt", "decimal(25,4) NULL");

                    // ── SB501000 Screen Registration ──────────────────────────
                    // Screen registration now handled by <ScreenWithRights> XML
                    // element (the Acumatica-native mechanism). The previous
                    // CustomizationPlugin SQL approach failed on cloud 24.208
                    // due to SiteMap schema differences.
                }

                WriteLog("[AesthetikContainers] All tables, columns, indexes, SiteMap, and access rights verified/created.");
            }
            catch (Exception ex)
            {
                WriteLog("[AesthetikContainers] ERROR: " + ex.GetType().FullName + ": " + ex.Message);
                if (ex.InnerException != null)
                    WriteLog("[AesthetikContainers] Inner: " + ex.InnerException.Message);
            }
        }

        // NOTE: SetSiteMapGraphType, GrantScreenAccess, DiagnoseAccessRights are dead code.
        // Screen registration now handled by <ScreenWithRights> XML element.
        // Previous SQL approach failed on cloud 24.208 (Invalid column name 'ScreenID').
        // Methods left in place to avoid CDATA encoding issues — safe to remove in next cleanup.

        private void SetSiteMapGraphType(SqlConnection conn, string screenID, string graphType)
        {
            // DEAD CODE — calls removed, <ScreenWithRights> handles this now
            // UPSERT SiteMap entry: INSERT if missing, UPDATE GraphType if blank
            string sql = @"
                IF NOT EXISTS (SELECT 1 FROM SiteMap WHERE ScreenID = @ScreenID AND CompanyID = 0)
                BEGIN
                    INSERT INTO SiteMap (CompanyID, NodeID, ScreenID, Title, Url, Graphtype, Icon, Expanded, Accessrights)
                    VALUES (0, NEWID(), @ScreenID, @Title, @Url, @GraphType, '', 0, 'G')
                END
                ELSE
                BEGIN
                    UPDATE SiteMap SET Graphtype = @GraphType
                    WHERE ScreenID = @ScreenID AND CompanyID = 0 AND (Graphtype IS NULL OR Graphtype = '')
                END";
            using (var cmd = new SqlCommand(sql, conn))
            {
                cmd.Parameters.AddWithValue("@ScreenID", screenID);
                cmd.Parameters.AddWithValue("@GraphType", graphType);
                cmd.Parameters.AddWithValue("@Title", "Container Maintenance");
                cmd.Parameters.AddWithValue("@Url", "~/Pages/SB/SB501000.aspx");
                int rows = cmd.ExecuteNonQuery();
                WriteLog(string.Format("  SiteMap {0} GraphType={1} — {2} row(s) affected", screenID, graphType, rows));
            }
        }

        private void GrantScreenAccess(SqlConnection conn, string screenID)
        {
            // Grant access to all roles by setting Accessrights = 'G' (Granted).
            // 'F' = Forbidden (default for new screens), '' = Inherited (still denied),
            // 'G' = Granted to all roles.
            string sql = @"
                UPDATE SiteMap SET Accessrights = 'G'
                WHERE ScreenID = @ScreenID AND CompanyID = 0";
            using (var cmd = new SqlCommand(sql, conn))
            {
                cmd.Parameters.AddWithValue("@ScreenID", screenID);
                int rows = cmd.ExecuteNonQuery();
                WriteLog(string.Format("  GrantAccess {0} — {1} row(s) updated", screenID, rows));
            }
        }

        private void DiagnoseAccessRights(SqlConnection conn, string screenID)
        {
            WriteLog("[DIAG] === Deep Schema Discovery ===");

            // 1. SMGraphPermission columns
            string sql1 = "SELECT c.name, t.name as type_name, c.max_length FROM sys.columns c JOIN sys.types t ON c.system_type_id = t.system_type_id WHERE c.object_id = OBJECT_ID('SMGraphPermission') ORDER BY c.column_id";
            using (var cmd = new SqlCommand(sql1, conn))
            {
                using (var rdr = cmd.ExecuteReader())
                {
                    while (rdr.Read())
                        WriteLog(string.Format("[DIAG] SMGraphPermission col: {0} ({1}, {2})", rdr[0], rdr[1], rdr[2]));
                }
            }

            // 2. Sample SMGraphPermission row for PO301000
            string sql2 = "SELECT TOP 3 * FROM SMGraphPermission WHERE ScreenID = 'PO301000'";
            using (var cmd = new SqlCommand(sql2, conn))
            {
                using (var rdr = cmd.ExecuteReader())
                {
                    int rowN = 0;
                    while (rdr.Read())
                    {
                        rowN++;
                        for (int i = 0; i < rdr.FieldCount; i++)
                            WriteLog(string.Format("[DIAG] PO301000_GP[{0}].{1} = {2}", rowN, rdr.GetName(i), rdr.IsDBNull(i) ? "NULL" : rdr[i].ToString().Substring(0, System.Math.Min(100, rdr[i].ToString().Length))));
                    }
                    if (rowN == 0) WriteLog("[DIAG] PO301000 NOT in SMGraphPermission");
                }
            }

            // 3. Check SB501000 in SMGraphPermission
            string sql3 = "SELECT * FROM SMGraphPermission WHERE ScreenID = @SID";
            using (var cmd = new SqlCommand(sql3, conn))
            {
                cmd.Parameters.AddWithValue("@SID", screenID);
                using (var rdr = cmd.ExecuteReader())
                {
                    int rowN = 0;
                    while (rdr.Read())
                    {
                        rowN++;
                        for (int i = 0; i < rdr.FieldCount; i++)
                            WriteLog(string.Format("[DIAG] SB501000_GP[{0}].{1} = {2}", rowN, rdr.GetName(i), rdr.IsDBNull(i) ? "NULL" : rdr[i].ToString().Substring(0, System.Math.Min(100, rdr[i].ToString().Length))));
                    }
                    WriteLog(string.Format("[DIAG] SB501000 in SMGraphPermission: {0} rows", rowN));
                }
            }

            // 4. Find all tables with 'Site' or 'Screen' or 'Node' in name
            string sql4 = "SELECT name FROM sys.tables WHERE name LIKE '%SiteMap%' OR name LIKE '%Screen%' OR name LIKE '%Node%Graph%' OR name LIKE '%GraphType%' ORDER BY name";
            using (var cmd = new SqlCommand(sql4, conn))
            {
                using (var rdr = cmd.ExecuteReader())
                {
                    while (rdr.Read())
                        WriteLog("[DIAG] RelatedTable: " + rdr[0]);
                }
            }

            // 5. SiteMap table — show ALL columns for SB501000 row if exists
            string sql5 = "SELECT TOP 1 * FROM SiteMap WHERE ScreenID = @SID";
            using (var cmd = new SqlCommand(sql5, conn))
            {
                cmd.Parameters.AddWithValue("@SID", screenID);
                using (var rdr = cmd.ExecuteReader())
                {
                    if (rdr.Read())
                    {
                        for (int i = 0; i < rdr.FieldCount; i++)
                            WriteLog(string.Format("[DIAG] SM_SB501000.{0} = {1}", rdr.GetName(i), rdr.IsDBNull(i) ? "NULL" : rdr[i].ToString().Substring(0, System.Math.Min(100, rdr[i].ToString().Length))));
                    }
                    else WriteLog("[DIAG] SB501000 NOT in SiteMap table");
                }
            }

            WriteLog("[DIAG] === End Discovery ===");
        }

        private void EnsureColumn(SqlConnection conn, string table, string column, string definition)
        {
            string sql = string.Format(
                "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('{0}') AND name = '{1}') " +
                "ALTER TABLE [{0}] ADD [{1}] {2};",
                table, column, definition);
            using (var cmd = new SqlCommand(sql, conn)) { cmd.ExecuteNonQuery(); }
            WriteLog(string.Format("  Column {0}.{1} — OK", table, column));
        }

        private void EnsureTable(SqlConnection conn, string table, string columnDefs)
        {
            string sql = string.Format(
                "IF OBJECT_ID('{0}', 'U') IS NULL CREATE TABLE [{0}] ({1});",
                table, columnDefs);
            using (var cmd = new SqlCommand(sql, conn)) { cmd.CommandTimeout = 60; cmd.ExecuteNonQuery(); }
            WriteLog(string.Format("  Table {0} — OK", table));
        }

        private void EnsureIndex(SqlConnection conn, string table, string indexName, string columns)
        {
            string sql = string.Format(
                "IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('{0}') AND name = '{1}') " +
                "CREATE NONCLUSTERED INDEX [{1}] ON [{0}] ({2});",
                table, indexName, columns);
            using (var cmd = new SqlCommand(sql, conn)) { cmd.ExecuteNonQuery(); }
            WriteLog(string.Format("  Index {0}.{1} — OK", table, indexName));
        }
    }
}

